using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.CycleSums;

internal sealed class ConsecutiveCycleSumsGraphDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Combinatorics/CycleSums/ConsecutiveCycleSumsGraph.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "A hub joined to a short initial block makes arbitrary core subsets and consecutive tail prefixes connected, with at most k minus one added edges.",
        H("The hub and tail construction for consecutive cycle sums"),
        Blocks(
            Node("cycle-sums-vertices", "Vertices selected by their labels", "vertices",
                "For a natural number n and a finite set S of natural labels, vertices n S consists of those v in Fin n for which v.val + 1 belongs to S.", DescribeRole.Definition),
            Node("cycle-sums-vertex-membership", "Membership under label selection", "mem_vertices",
                "For every natural n, finite label set S and vertex v in Fin n, v belongs to vertices n S if and only if v.val + 1 belongs to S.", DescribeRole.Theorem),
            Node("cycle-sums-vertex-sum", "Label selection preserves sums", "sum_vertices",
                "For every natural n and finite set S of natural labels, if every x in S satisfies 1 ≤ x ≤ n, the sum of v.val + 1 over vertices n S equals the sum of x over S. Each positive bounded label has the unique vertex with value x minus one.", DescribeRole.Theorem),
            Node("cycle-sums-completion", "Cycle with a hub", "completion",
                "For natural n and k with n positive, completion n k is the supremum of cycleGraph n and the simple graph generated by the unordered edges joining vertex zero to a vertex v with 2 ≤ v.val ≤ k. Its vertices retain their original consecutive labels.", DescribeRole.Definition),
            Node("cycle-sums-cycle-inclusion", "The original cycle is retained", "cycle_le_completion",
                "For every natural n and k with n positive, cycleGraph n is a subgraph of completion n k.", DescribeRole.Theorem),
            Node("cycle-sums-edge-bound", "The number of newly added edges", "added_edges_le",
                "For every natural n and k with n positive, the natural cardinality of the edge set of completion n k minus the edge set of cycleGraph n is at most k minus one. The difference is contained in the star edges, indexed by vertex values from two through k.", DescribeRole.Theorem),
            Node("cycle-sums-hub-tail-connected", "Core subsets with a tail prefix", "hub_tail_connected",
                "Let n be positive and let k and j satisfy k < n and k ≤ j ≤ n. For every finite set S of natural labels, if every x in S lies between two and k, the subgraph of completion n k induced by vertices with labels in {1} ∪ S ∪ {k + 1, …, j} is connected. Core vertices and the first tail vertex are adjacent to the hub; every later tail vertex has its predecessor in the set.", DescribeRole.Theorem),
            Node("cycle-sums-interval-connected", "Consecutive labels induce a connected graph", "interval_connected",
                "For every natural n, k, l and j with n positive and 1 ≤ l ≤ j ≤ n, the subgraph of completion n k induced by vertices with labels from l through j is connected. Successive labels are adjacent along the original cycle path.", DescribeRole.Theorem)
        ), []));

    private static DocumentBlock Node(string id, string title, string declaration,
        string prose, DescribeRole role) =>
        Describe.Lean(DescribeId.Create(id), DeclarationHandle.Create(Prefix + declaration),
            H(title), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text(prose))), role);
}
